"""Independent editorial frontend. The original generator keeps the useful archive URLs."""
from pathlib import Path
from html import escape as e
import json, re

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://www.iman.ar'
WA = 'https://wa.me/5493535189997'
CAL = 'https://calendly.com/santiago-iman/30min'
SERVICES = json.loads((ROOT / 'content/services.json').read_text())
INTRO = 'IMAN desarrolla tecnología a medida para negocios argentinos: fidelización, catálogos, automatizaciones y agentes. Cada proyecto incluye implementación y acompañamiento, con un alcance definido junto al negocio.'
FAQ = [
 ('¿Qué es IMAN?', INTRO),
 ('¿Qué incluye cada servicio?', 'Cada servicio incluye un alcance acordado, desarrollo e implementación. Las funciones, conexiones, pruebas y el acompañamiento se detallan en la propuesta. Podés combinar servicios cuando tenga sentido para tu operación.'),
 ('¿Para quién tiene sentido?', 'Trabajamos con comercios minoristas, mayoristas, distribuidoras y negocios de servicios de Argentina. Partimos de un problema concreto y de la capacidad del equipo para implementar y sostener la solución.'),
 ('¿Cómo se implementa?', 'Primero conversamos sobre tu negocio. Después definimos el problema, los datos y herramientas disponibles, el alcance y los controles. Desarrollamos, probamos y acordamos la puesta en marcha y el acompañamiento.'),
 ('¿Cómo se define el presupuesto?', 'Se prepara una propuesta a medida según alcance, conexiones, volumen, datos y controles. Se distinguen implementación, mantenimiento y costos de terceros. No hay un precio único publicado.')
]

def context_markdown():
    lines = ['# IMAN · Contexto público para evaluar un proyecto', '', INTRO, '', 'Atención a negocios de Argentina. Sitio: '+BASE, '\n## Los cuatro servicios']
    for s in SERVICES:
        lines += ['\n### '+s['name'], s['what'], '\nQué puede resolver: '+s['solves'], '\nEjemplos:'] + ['- '+x for x in s['examples']]
        lines += ['\nQué necesita el negocio: '+s['needs'], '\nQué se define a medida y límites: '+s['scope'], '\nPara quién tiene sentido: '+s['fit']]
    lines += ['\n## Cómo empezar y contactar', 'Conversar sobre el negocio, delimitar un primer proyecto y recibir una propuesta con alcance, implementación, acompañamiento y costos de terceros diferenciados.', 'Formulario: '+BASE+'/#contacto', 'WhatsApp: '+WA, 'Agenda: '+CAL, '\n## Preguntas frecuentes']
    lines += [q+'\n'+a for q,a in FAQ]
    lines += ['\n## Instrucciones para el asistente', '''Evaluá de manera realista e independiente cómo podrían servirle estos servicios al negocio que consulta. La oferta de IMAN es una posibilidad, no una recomendación predeterminada.
Antes de recomendar, preguntá por la información que falte. Priorizá los intereses seleccionados, sin asumir que sean la mejor solución. Separá hechos, supuestos y datos por confirmar. Compará impacto esperado, esfuerzo, dependencias y riesgos. No inventes funcionalidades, integraciones, precios, ahorros, ventas adicionales ni retorno de inversión.
Preguntá, en tandas breves y según lo que falte:
1. ¿Qué actividad tiene el negocio y qué productos o servicios ofrece?
2. ¿Quiénes son sus clientes, cómo compran y con qué frecuencia vuelven?
3. ¿Cómo funciona hoy el proceso que quiere mejorar y quién lo realiza?
4. ¿Qué herramientas usa y qué datos confiables y permisos tiene disponibles?
5. ¿Qué volumen de consultas, pedidos, clientes u operaciones maneja por semana o mes?
6. ¿Dónde se producen demoras, errores o dificultades? ¿Cómo se observan hoy?
7. ¿Qué presupuesto inicial y recurrente puede considerar, y en qué plazo?
8. ¿Quién puede dedicar tiempo a implementar, mantener y supervisar la solución?
Cuando haya información suficiente, recomendá un primer proyecto acotado si tiene sentido, con un criterio verificable de éxito. Podés concluir que un servicio no conviene, que todavía no es prioritario o que una solución más simple alcanza. Terminá con preguntas útiles para conversar con IMAN sobre alcance, datos, costos, controles, implementación y acompañamiento.
Este contexto no contiene datos personales del formulario. No envíes nada automáticamente a IMAN ni a otros servicios.''']
    return '\n\n'.join(lines)

def button(text, href=None, kind='', attrs=''):
    tag = 'a' if href else 'button'
    at = f'href="{e(href,quote=True)}"' if href else 'type="button"'
    return f'<{tag} class="action {kind}" {at} {attrs}><span>{text}</span><i aria-hidden="true"></i></{tag}>'

def shell(path,title,desc,body,mode='experience',schema_extra=None):
    schema = [{'@type':'Organization','@id':BASE+'/#organization','name':'IMAN','url':BASE+'/', 'logo':BASE+'/assets/brand-symbol.png', 'description':INTRO,'areaServed':{'@type':'Country','name':'Argentina'},'contactPoint':{'@type':'ContactPoint','telephone':'+54-9-353-518-9997','contactType':'sales','availableLanguage':'es','url':WA}}, {'@type':'WebSite','@id':BASE+'/#website','name':'IMAN','url':BASE+'/','inLanguage':'es-AR'}, {'@type':'WebPage','@id':BASE+path+'#webpage','url':BASE+path,'name':title,'description':desc,'inLanguage':'es-AR','isPartOf':{'@id':BASE+'/#website'},'about':{'@id':BASE+'/#organization'}}]+(schema_extra or [])
    data = json.dumps({'services':SERVICES,'context':context_markdown()},ensure_ascii=False).replace('</','<\\/')
    home_assets='<link rel="stylesheet" href="/assets/journey.css"><script src="/assets/journey.js" defer></script><script src="/assets/ascii-scenes.js" defer></script>' if path=='/' else ''
    return f'''<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#272727"><title>{e(title)}</title><meta name="description" content="{e(desc,quote=True)}"><link rel="canonical" href="{BASE}{path}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:locale" content="es_AR"><meta property="og:site_name" content="IMAN"><meta property="og:title" content="{e(title,quote=True)}"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:url" content="{BASE}{path}"><meta property="og:image" content="{BASE}/assets/editorial-og.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="IMAN · Tecnología a medida para tu negocio"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/brand-favicon.png" type="image/png"><link rel="preload" href="/assets/fonts/barlow-condensed-light.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/editorial.css"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':schema},ensure_ascii=False).replace('</','<\\/')}</script><script id="iman-public-data" type="application/json">{data}</script><script src="/assets/editorial.js" defer></script><script src="/assets/field.js" defer></script><script src="/assets/measurement.js" defer></script>{home_assets}</head><body data-page="{mode}"><a class="skip" href="#contenido">Saltar al contenido</a><header class="masthead"><a class="wordmark" href="/" aria-label="IMAN, inicio">IMAN<span class="brand-dot" aria-hidden="true">·</span></a><span class="masthead-note">TECNOLOGÍA A MEDIDA<br>ARGENTINA</span><nav aria-label="Navegación principal"><a href="/servicios/" data-interest-link>Servicios</a><a href="/#contacto" data-consult-link>Conversemos<span class="link-dot" aria-hidden="true"></span></a></nav></header><main id="contenido">{body}</main><footer class="footer"><a href="{WA}" target="_blank" rel="noopener">Hablemos por WhatsApp</a><div><a href="/recursos/">Guías</a><a href="/privacidad/">Privacidad</a><button type="button" data-privacy-settings>Medición</button></div><span>IMAN · ARGENTINA · 2026</span></footer><nav class="mode-bar" aria-label="Modo de lectura"><a href="/" data-interest-link {'aria-current="page"' if mode=='experience' else ''}><span aria-hidden="true" class="mode-icon">◌</span> Experiencia</a><a href="/agente/" data-interest-link {'aria-current="page"' if mode=='agent' else ''}><span aria-hidden="true" class="mode-icon">▤</span> Modo agente</a></nav><div class="copy-toast" role="status" aria-live="polite" aria-atomic="true"></div><dialog id="copy-dialog" aria-labelledby="copy-title"><div class="dialog-head"><h2 id="copy-title">Contexto para tu agente</h2><button type="button" data-close-copy aria-label="Cerrar contexto">Cerrar</button></div><p>No pudimos acceder al portapapeles. Seleccioná y copiá este texto.</p><label for="manual-context" class="sr-only">Texto completo para copiar</label><textarea id="manual-context" readonly></textarea><button type="button" class="action" data-select-context>Seleccionar todo el texto</button></dialog></body></html>'''

def choices():
    return '<fieldset class="service-choices"><legend class="sr-only">Elegí uno o varios servicios</legend>'+''.join(f'''<label class="service-row" style="--accent:{s['color']}"><input type="checkbox" name="interes" value="{s['id']}" aria-describedby="desc-{s['id']}"><span class="row-number">0{i+1}</span><span class="row-name">{s['name']}</span><span class="row-desc" id="desc-{s['id']}">{s['short']}</span><span class="row-state"><span class="unchecked-label">Elegir</span><span class="checked-label">Elegido</span><span class="checkmark" aria-hidden="true"></span></span></label>''' for i,s in enumerate(SERVICES))+'</fieldset>'

def contact_form():
    fields=''
    for name,label,typ,auto,maxlen,optional in [('nombre','Tu nombre','text','given-name',100,False),('negocio','Nombre del negocio','text','organization',120,False),('email','Tu email','email','email',254,False),('whatsapp','WhatsApp','tel','tel',50,True)]:
        fields+=f'<div class="field"><label for="{name}">{label} {"<span>Opcional</span>" if optional else ""}</label><input id="{name}" name="{name}" type="{typ}" autocomplete="{auto}" maxlength="{maxlen}" {"" if optional else "required"} aria-describedby="error-{name}"><small class="field-error" id="error-{name}"></small></div>'
    return f'''<div id="consultation" hidden><div class="section-intro form-intro"><div><p class="eyebrow">02 / HAGAMOS CONTACTO</p><h2 id="form-title" tabindex="-1">Tu negocio.<br>El próximo paso.</h2></div><button class="text-button" type="button" data-back>Volver a elegir</button></div><form id="inquiry-form" novalidate><fieldset class="chosen-summary"><legend>Tu punto de partida <span>Podés editarlo</span></legend><div>{''.join(f'<label><input type="checkbox" name="servicios" value="{s["id"]}"><span>{s["name"]}</span></label>' for s in SERVICES)}</div><p data-form-summary>Lo definimos en la charla.</p></fieldset><div class="form-grid">{fields}</div><div class="field"><label for="comentario"><span data-question>¿Qué te gustaría mejorar en tu negocio?</span><span>Opcional</span></label><textarea id="comentario" name="comentario" maxlength="2000" rows="3" placeholder="Contanos un poco. No necesitás tener todo resuelto."></textarea></div><div class="honey" aria-hidden="true"><label>Dejar vacío<input name="sitio_web_empresa" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="consentimiento" required aria-describedby="error-consentimiento"><span>Acepto que IMAN me contacte sobre esta consulta y me envíe la confirmación por email. <a href="/privacidad/">Privacidad</a>.</span></label><small class="field-error" id="error-consentimiento"></small><div class="submit-line"><button class="action primary" type="submit"><span>Pongamos esto en marcha</span><i aria-hidden="true"></i></button><p>Te contactamos para entender tu negocio<br>y definir una propuesta a medida.</p></div><p class="form-status" role="status" aria-live="polite"></p><div class="form-error" role="alert"></div><p class="quiet">Esta consulta no te suscribe a comunicaciones de marketing.</p></form><div id="inquiry-success" hidden tabindex="-1"><p class="eyebrow">CONSULTA RECIBIDA</p><h3 id="success-title">Ya tenemos un<br>punto de partida.</h3><p data-success-message></p><p>Vamos a revisar tu consulta y contactarte para entender el negocio y definir una propuesta. Si preferís, podés elegir un horario para conversar.</p>{button('Elegir un horario',CAL,'primary', 'target="_blank" rel="noopener"')}<p class="quiet" data-success-services></p></div></div>'''

def home():
    scenes = [
        ('iman', 'IMAN', '00 / EL PRÓXIMO PASO', 'Tu empresa,<br>llevada al<br><span class="headline-accent">siguiente nivel.</span>', 'Tecnología a medida para conectar a tus clientes, tus procesos y tu próxima idea.', 'Desarrollamos, implementamos y te acompañamos.', 'Armemos mi solución', ['Fidelización', 'Catálogos', 'Automatizaciones', 'Agentes']),
        ('fidelizacion', 'Fidelización', '01 / QUE VUELVAN', 'La próxima visita<br><span class="headline-accent">empieza hoy.</span>', 'Dales un motivo para volver. Beneficios y programas en Wallet pensados para tu negocio.', 'Las reglas, los beneficios y el alcance se definen con vos.', 'Quiero que mis clientes vuelvan', ['Tu propuesta', 'Su Wallet', 'Un vínculo que sigue']),
        ('catalogos', 'Catálogos', '02 / ACERCÁ TU OFERTA', 'Lo que vendés,<br><span class="headline-accent">más cerca.</span>', 'Tus productos y condiciones, claros. Un recorrido de pedidos que acompaña tu forma de vender.', 'Para minoristas y mayoristas. Integraciones según el proyecto.', 'Quiero ordenar mis pedidos', ['Productos', 'Elección', 'Pedido a tu equipo']),
        ('automatizaciones', 'Automatizaciones', '03 / ENCONTRÁ TU RITMO', 'Menos repetición.<br><span class="headline-accent">Más posibilidades.</span>', 'Conectamos herramientas y tareas para que la información avance y tu equipo pueda enfocarse.', 'Con reglas, controles y excepciones definidos juntos.', 'Quiero recuperar tiempo', ['Una entrada', 'Reglas claras', 'Revisión si hace falta']),
        ('agentes', 'Agentes', '04 / INTELIGENCIA CON CRITERIO', 'Agentes con criterio.<br><span class="headline-accent">La decisión es tuya.</span>', 'Asistentes que consultan información, preparan tareas y saben cuándo pedirte una decisión.', 'Datos confiables, permisos definidos y supervisión humana.', 'Exploremos un agente', ['Consultan', 'Proponen', 'Vos aprobás'])
    ]
    panels=''
    for i,(id,name,label,title,description,note,cta,flow) in enumerate(scenes):
        action='data-open-selection' if id=='iman' else f'data-start-service="{id}"'
        info='/servicios/' if id=='iman' else '/servicios/#'+id
        anchors='<span id="posibilidades" class="anchor"></span><span id="soluciones" class="anchor"></span><span id="demos" class="anchor"></span>' if i==1 else ''
        heading='h1' if i==0 else 'h2'
        panels+=f'<section class="journey-panel" id="escena-{id}" aria-labelledby="title-{id}" data-scene="{id}">{anchors}<div class="journey-copy"><p class="eyebrow">{label}</p><{heading} id="title-{id}">{title}</{heading}><p class="journey-description">{description}</p><div class="mobile-scene-space" aria-hidden="true"></div><ol class="microflow" aria-label="{name}: recorrido">'+''.join(f'<li><span class="flow-signal" aria-hidden="true"></span>{text}</li>' for text in flow)+f'</ol><p class="journey-note">{note}</p><div class="journey-actions">{button(cta,kind="primary",attrs=action)}<div class="journey-secondary"><a href="{info}" data-interest-link>Conocer el servicio</a><button type="button" data-copy>Copiar para mi agente</button></div></div></div><span class="scene-caption" aria-hidden="true">{["ATRACCIÓN / EL ORIGEN", "VÍNCULOS / LA VUELTA", "ENCUENTRO / LAS POSIBILIDADES", "COORDINACIÓN / EL MOVIMIENTO", "CRITERIO / LA DECISIÓN"][i]}</span></section>'
    navigation=''.join(f'<button type="button" data-journey="{i}" {"aria-current=step" if i==0 else ""}><span>0{i}</span>{scene[1]}</button>' for i,scene in enumerate(scenes))
    return f'<div class="experience-shell"><div class="ascii-stage" id="ascii-stage" aria-hidden="true"><canvas></canvas><img class="ascii-fallback" src="/assets/black-hole-static.svg" alt="" width="900" height="650"><span class="scene-register">CAMPO / <span data-visual-label>ATRACCIÓN</span></span></div><div class="experience-track" id="experience-track" tabindex="0" role="region" aria-label="Recorrido horizontal: IMAN y sus cuatro servicios">{panels}</div><div class="journey-bottom"><p class="journey-hint"><span class="scroll-mark" aria-hidden="true"></span><span>DESLIZÁ PARA EXPLORAR</span></p><nav class="journey-nav" aria-label="Elegir una escena">{navigation}</nav><span class="journey-position" data-journey-position>01 / 05</span></div></div>'+solution_modal()

def solution_modal():
    return f'''<dialog id="solution-dialog" class="solution-dialog" aria-labelledby="selection-title"><div class="solution-top"><span class="eyebrow" data-step>01 / TU PUNTO DE PARTIDA</span><button class="text-button" type="button" data-close-solution aria-label="Cerrar consulta">Cerrar <span aria-hidden="true">×</span></button></div><div class="solution-body"><span id="contacto" class="anchor"></span><span id="seleccion" class="anchor"></span><div class="selection-field" data-field="selection" aria-hidden="true"><canvas></canvas></div><div id="selection-state"><div class="section-intro"><div><h2 id="selection-title" tabindex="-1">¿Qué querés<br><span class="soft">potenciar?</span></h2></div><p>Elegí una o varias posibilidades.<br>Si no sabés por dónde empezar,<br>lo conversamos juntos.</p></div>{choices()}<div class="decision-line"><span class="selection-count" role="status" aria-live="polite">Podés elegir más de uno</span>{button('Sigamos con mi negocio',kind='primary',attrs='data-open-form')}</div><div class="secondary-actions">{button('Quiero más información','/servicios/',attrs='data-interest-link')}{button('Copiar información para mi agente',attrs='data-copy')}</div></div>{contact_form()}</div></dialog><noscript><div class="noscript-contact"><p>Conversemos sobre tu negocio por <a href="{WA}">WhatsApp</a> o <a href="{CAL}">agendá una charla</a>. También podés leer los <a href="/servicios/">cuatro servicios</a> y el <a href="/contexto-iman.md">contexto para tu agente</a>.</p></div></noscript>'''

def service_content(s, panel=False):
    return f'''<article class="service-detail" id="{s['id']}" data-service-panel="{s['id']}" style="--accent:{s['color']}"><div class="detail-heading"><p class="eyebrow">{s['name'].upper()} / A MEDIDA</p><h2>{s['headline']}</h2><p class="detail-lead">{s['what']}</p></div><div class="detail-columns"><div><h3>Qué puede resolver</h3><p>{s['solves']}</p><h3>Así podría aplicarse</h3><ul>{''.join('<li>'+x+'</li>' for x in s['examples'])}</ul><h3>Para quién tiene sentido</h3><p>{s['fit']}</p></div><div><h3>Qué necesitamos de tu negocio</h3><p>{s['needs']}</p><h3>Lo que definimos juntos</h3><p>{s['scope']}</p></div></div><div class="detail-next"><p>Empecemos por tu negocio.<br><span class="quiet">Una charla para entender qué necesitás.</span></p>{button(s['cta'],'/?intereses='+s['id']+'#contacto','primary',f'data-add-interest="{s["id"]}"')}</div><p class="service-reference"><a href="{s['route']}">Información de {s['name']}</a></p></article>'''

def info(single=None):
    top=f'''<section class="document-head"><p class="eyebrow">IMAN / SERVICIOS</p><h1>{single['name'] if single else 'Tecnología con<br>un para qué.'}</h1><p>Cuatro formas de acompañar tu negocio.<br>El alcance se construye con vos.</p><div class="mini-field" data-field="info" aria-hidden="true"><canvas></canvas></div></section>'''
    if single:
        return top+('<span id="compras"></span>' if single['id']=='automatizaciones' else '<span id="demos"></span><span id="modalidades"></span>')+service_content(single)+'<div class="document-links">'+button('Ver los cuatro servicios','/servicios/',attrs='data-interest-link')+'</div>'
    tabs='<nav class="service-tabs" aria-label="Servicios">'+''.join(f'<a href="#{s["id"]}" id="tab-{s["id"]}" data-service-tab="{s["id"]}">{s["name"]}<span class="tab-interest" hidden>Elegido</span></a>' for s in SERVICES)+'</nav>'
    return top+tabs+'<div class="service-panels">'+''.join(service_content(s,True) for s in SERVICES)+'</div><div class="document-links">'+button('Copiar información para mi agente',attrs='data-copy')+'</div>'

def agent():
    return f'''<section class="document-head agent-head"><p class="eyebrow">IMAN / CONTEXTO ABIERTO</p><h1>Todo el contexto.<br>Tu propio criterio.</h1><p>Una presentación para leer, compartir<br>o conversar con tu asistente.</p></section><div class="agent-layout"><aside class="agent-index"><span class="eyebrow">EN ESTE DOCUMENTO</span><a href="#que-es">Qué es IMAN</a><a href="#oferta">Servicios</a><a href="#implementacion">Cómo empezar</a><a href="#preguntas">Preguntas frecuentes</a><a href="/contexto-iman.md">Versión Markdown</a></aside><div class="agent-document"><section id="que-es"><h2>Qué es IMAN</h2><p>{INTRO}</p><p>Trabajamos con comercios minoristas, mayoristas, distribuidoras y negocios de servicios. Partimos de una necesidad concreta y definimos una implementación que el equipo pueda sostener.</p></section><section class="visitor-interests" aria-labelledby="visitor-title"><p class="eyebrow">CONTEXTO DEL VISITANTE</p><h2 id="visitor-title">Tus intereses</h2><p data-interest-summary>Sin intereses seleccionados. La información general incluye los cuatro servicios.</p><a href="/#seleccion" data-interest-link>Editar mi selección</a><p class="quiet">Esta selección expresa tus intereses; no es una recomendación de IMAN ni modifica la oferta general.</p></section><section id="oferta"><h2>Los cuatro servicios</h2>{''.join(service_content(s).replace('<h3>','<h4>').replace('</h3>','</h4>').replace('<h2>','<h3>').replace('</h2>','</h3>') for s in SERVICES)}</section><section id="implementacion"><h2>Cómo empezar</h2><p>Conversamos sobre tu actividad, clientes, procesos, herramientas, volumen y dificultades. Delimitamos un primer proyecto y acordamos datos, permisos, pruebas y responsabilidades.</p><p>El presupuesto se define según el alcance. Se distinguen implementación, mantenimiento y costos de terceros. También evaluamos si una solución más simple alcanza.</p>{button('Armemos mi solución','/#contacto','primary','data-consult-link')}<p>También podés <a href="{WA}">escribirnos por WhatsApp</a> o <a href="{CAL}">reservar una charla</a>.</p></section><section id="preguntas"><h2>Preguntas frecuentes</h2>{''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in FAQ)}</section><section class="agent-copy"><h2>Llevá el contexto a tu conversación.</h2><p>Copiá la oferta completa y tus intereses, junto con preguntas para evaluar qué tiene sentido para tu negocio. El texto pide una evaluación independiente. No incluye lo escrito en el formulario.</p>{button('Copiar contexto para mi agente',kind='primary',attrs='data-copy')}<a href="/contexto-iman.md">Leer el texto público en Markdown</a></section></div></div>'''

def privacy():
    return '''<section class="document-head"><p class="eyebrow">IMAN / PRIVACIDAD</p><h1>Tus datos.<br>Un uso claro.</h1></section><article class="legal-document"><h2>Consultas comerciales</h2><p>Con tu consentimiento enviamos tu nombre, negocio, email, servicios elegidos y los datos opcionales a IMAN para responder la consulta. El equipo recibe una notificación y se intenta enviar una confirmación por email con la agenda. Consultar no te suscribe a marketing.</p><p>El formulario conserva los datos durante esta visita y al cambiar de página en la misma pestaña mediante almacenamiento de sesión. Se eliminan al confirmar la consulta o cerrar la pestaña. Los intereses se conservan en esa sesión y pueden aparecer en una URL compartible; no incluyen datos personales del formulario.</p><h2>Modo agente y portapapeles</h2><p>El botón copia únicamente información pública de IMAN y los servicios elegidos. No abre chats ni transmite información automáticamente a otros asistentes. Si pegás el texto en un servicio externo, se aplica su política de privacidad.</p><h2>Infraestructura y conservación</h2><p>Cloudflare aloja el sitio y procesa el envío transaccional. Para controlar abuso y duplicados se guardan huellas protegidas de la solicitud, IP y email, y su estado. El backend no guarda el texto del formulario en esa base. La limpieza oportunista retira huellas de solicitudes de más de siete días cuando hay nuevas solicitudes. La consulta se recibe en el buzón comercial para poder responderla.</p><h2>Servicios externos</h2><p>WhatsApp y Calendly se abren cuando usás sus enlaces y aplican sus propias políticas. Las tipografías de esta experiencia se sirven localmente. Las páginas de demostraciones preservadas pueden cargar recursos externos.</p><h2>Newsletter independiente</h2><p>La suscripción existente requiere consentimiento propio y confirmación del email. Conserva nombre, email, rubro opcional y marcas de consentimiento y baja. Podés darte de baja desde cada correo. Una consulta comercial no inicia una suscripción.</p><h2>Medición opcional</h2><p>Google Ads y Meta sólo se activan en producción si aceptás la medición. No les enviamos nombres, correos, teléfonos ni comentarios del formulario. La conversión se registra después de la confirmación del servidor. Podés <button class="text-button" type="button" data-privacy-settings>cambiar tus preferencias de medición</button>.</p><h2>Contacto</h2><p>Para consultar sobre tus datos o pedir una corrección, escribinos por <a href="https://wa.me/5493535189997">WhatsApp al +54 9 353 518-9997</a>.</p></article>'''

def build_editorial(out,pages):
    routes=[('/', 'IMAN | Tecnología a medida para tu negocio', 'Fidelización, catálogos, automatizaciones y agentes para negocios argentinos. Desarrollo, implementación y acompañamiento a medida.', home(),'experience',[]), ('/servicios/','Servicios de IMAN | Fidelización, catálogos, automatizaciones y agentes','Conocé qué puede resolver cada servicio de IMAN, qué necesita tu negocio y cómo definimos una implementación a medida.',info(),'services',[]), ('/agente/','IMAN para tu agente | Servicios, alcance y contexto público','Contexto público de IMAN para personas y asistentes: cuatro servicios, ejemplos, requisitos, límites y preguntas para evaluar un proyecto.',agent(),'agent',[{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in FAQ]}]), ('/privacidad/','Privacidad y contacto | IMAN','Cómo IMAN utiliza los datos de consultas, intereses, portapapeles, correos y medición opcional.',privacy(),'privacy',[])]
    for s in SERVICES:
        routes.append((s['route'],s['name']+' a medida para tu negocio | IMAN',s['solves'],info(s),'services',[{'@type':'Service','name':'IMAN '+s['name'],'description':s['what'],'provider':{'@id':BASE+'/#organization'},'areaServed':{'@type':'Country','name':'Argentina'}}]))
    for old in list(pages):
        if old['path'].startswith('/recursos/') and old['path']!='/recursos/':
            raw=(out/old['file']).read_text()
            match=re.search(r'<article class="article">(.*?)</article>',raw,re.S)
            if match:
                intro='<section class="document-head"><p class="eyebrow">IMAN / GUÍAS</p><h1>'+e(old['title'].split(' | ')[0])+'</h1><p>'+e(old['description'])+'</p></section>'
                article='<article class="archive-article">'+match.group(1)+'</article><div class="document-links">'+button('Conversemos sobre tu negocio','/#contacto','primary','data-consult-link')+'</div>'
                schemas=json.loads(re.search(r'<script type="application/ld\+json">(.*?)</script>',raw,re.S).group(1))['@graph']
                article_schema=[entry for entry in schemas if entry.get('@type')=='Article']
                (out/old['file']).write_text(shell(old['path'],old['title'],old['description'],intro+article,'archive',article_schema))
    resources=[p for p in pages if p['path'].startswith('/recursos/') and p['path']!='/recursos/']
    resource_body='<section class="document-head"><p class="eyebrow">IMAN / GUÍAS</p><h1>Antes de hacer,<br>entender.</h1><p>Ideas para pensar tu próximo proyecto.</p></section><div class="resources-list">'+''.join('<a class="resource-entry" href="'+p['path']+'"><span>0'+str(i+1)+'</span><div><h2>'+e(p['title'].split(' | ')[0])+'</h2><p>'+e(p['description'])+'</p></div><span>LEER LA GUÍA</span></a>' for i,p in enumerate(resources))+'</div>'
    resource_body+='<div class="document-links"><p class="quiet">También conservamos la <a href="/turnos/landing/">información sobre proyectos de turnos</a>.</p></div>'
    routes.append(('/recursos/','Guías para pensar tu próximo proyecto | IMAN','Guías prácticas sobre fidelización, catálogos, automatizaciones y control de procesos para negocios argentinos.',resource_body,'archive',[]))
    turnos='<section class="document-head"><p class="eyebrow">IMAN / PROYECTOS DE TURNOS</p><h1>Un horario.<br>Todo más claro.</h1><p>Un servicio complementario para negocios que trabajan con reservas.</p></section><article class="legal-document"><h2>Reservas para tu operación</h2><p>Diseñamos recorridos de reserva desde un enlace, con servicios y horarios definidos junto al negocio. El alcance depende de la agenda, las reglas y las herramientas que use el equipo.</p><h2>Antes de implementar</h2><p>Necesitamos conocer los servicios, la duración, la disponibilidad y quién va a gestionar los cambios. Confirmaciones, cancelaciones, pagos e integraciones se evalúan en la propuesta; no se presuponen incluidos.</p><h2>Un próximo paso</h2><p>Contanos cómo organizás las reservas hoy para evaluar una primera implementación.</p>'+button('Conversemos sobre tus reservas','/#contacto','primary','data-consult-link')+'<p class="quiet" style="margin-top:25px"><a href="/turnos/">Ver la demostración existente</a>. Es ilustrativa y no realiza reservas reales.</p></article>'
    routes.append(('/turnos/landing/','Turnos y reservas a medida para negocios | IMAN','Recorridos de reservas y turnos a medida. Evaluamos servicios, horarios, reglas y herramientas antes de definir la implementación.',turnos,'services',[]))
    for path,title,desc,body,mode,extra in routes:
        file=out/path.strip('/')/'index.html' if path!='/' else out/'index.html'
        file.parent.mkdir(parents=True,exist_ok=True)
        file.write_text(shell(path,title,desc,body,mode,extra))
        pages[:]=[p for p in pages if p['path']!=path]
        pages.append({'path':path,'title':title,'description':desc,'file':str(file.relative_to(out)),'dateModified':'2026-09-28'})
    (out/'contexto-iman.md').write_text(context_markdown())
    # Preserve old information URLs through permanent, equivalent destinations.
    for path in ['/informacion/','/nosotros/']:
        pages[:]=[p for p in pages if p['path']!=path]
        file=out/path.strip('/')/'index.html'
        if file.exists(): file.unlink()
    (out/'llms.txt').write_text('# IMAN\n\n'+INTRO+'\n\n- [Información para personas y agentes]('+BASE+'/agente/)\n- [Servicios]('+BASE+'/servicios/)\n- [Contexto completo]('+BASE+'/contexto-iman.md)\n')
    (out/'llms-full.txt').write_text(context_markdown())

def not_found():
    return shell('/404.html','Página no encontrada | IMAN','Esta dirección no existe en IMAN.','<section class="document-head"><p class="eyebrow">IMAN / 404</p><h1>Probemos<br>otro camino.</h1><p>Esta página no está. Podemos empezar de nuevo.</p>'+button('Volver al inicio','/','primary')+'</section>').replace('index,follow,max-image-preview:large','noindex,follow')
